//! The Rust half of the release-endorsement v2 vectors
//! (packages/protocol/test-vectors/release-endorsement-v2/vectors.json,
//! generated by tools/release-pq-vectors.ts). Every statement must rebuild
//! byte for byte and every case must end with the TypeScript code.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]

use flagship_crypto::release::{
    CompanionWire, Pin, ReleaseError, ReleaseV1, classify, v1_canonical, v1_digest, v2_statement,
    verify_companion, verify_release_bindings,
};
use flagship_crypto::trust::{BindingWire, hex};
use serde_json::Value;
use std::path::PathBuf;

fn vectors() -> Value {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../packages/protocol/test-vectors/release-endorsement-v2/vectors.json");
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

fn opt(v: &Value) -> Option<&str> {
    v.as_str()
}

struct Owned<'a> {
    sigs: Vec<(&'a str, &'a str)>,
    v: &'a Value,
}

impl<'a> Owned<'a> {
    fn new(v: &'a Value) -> Self {
        let sigs = v["signatures"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| (s["pubkey"].as_str().unwrap(), s["sig"].as_str().unwrap()))
            .collect();
        Self { sigs, v }
    }
    fn view(&self) -> ReleaseV1<'_> {
        let v = self.v;
        ReleaseV1 {
            release_id: v["releaseId"].as_str().unwrap(),
            semver_tag: v["semverTag"].as_str().unwrap(),
            commit_hash: v["commitHash"].as_str().unwrap(),
            previous_release_id: opt(&v["previousReleaseId"]),
            previous_commit_hash: opt(&v["previousCommitHash"]),
            intermediate_merkle_root: v["intermediateMerkleRoot"].as_str().unwrap(),
            endorsed_notes: opt(&v["endorsedNotes"]),
            issued_at: v["issuedAt"].as_str().unwrap(),
            signed_by: v["signedBy"].as_str().unwrap(),
            signatures: &self.sigs,
        }
    }
}

const COMPANION_KEYS: [&str; 8] = [
    "commitHash",
    "keyId",
    "kind",
    "releaseId",
    "signature",
    "suite",
    "v1Digest",
    "version",
];

/// The JSON-level checks TypeScript makes before the typed ones.
fn companion(v: &Value) -> Result<CompanionWire<'_>, ReleaseError> {
    let o = v.as_object().ok_or(ReleaseError::PqMalformed)?;
    let mut keys: Vec<&str> = o.keys().map(String::as_str).collect();
    keys.sort_unstable();
    if keys != COMPANION_KEYS {
        return Err(ReleaseError::PqMalformed);
    }
    let s = |k: &str| v[k].as_str().ok_or(ReleaseError::PqMalformed);
    Ok(CompanionWire {
        kind: s("kind")?,
        version: v["version"].as_u64().ok_or(ReleaseError::PqMalformed)?,
        release_id: s("releaseId")?,
        commit_hash: s("commitHash")?,
        v1_digest: s("v1Digest")?,
        key_id: s("keyId")?,
        suite: s("suite")?,
        signature: s("signature")?,
    })
}

fn binding(v: &Value) -> BindingWire<'_> {
    BindingWire {
        version: v["v"].as_u64().unwrap() as u8,
        role: v["role"].as_str().unwrap(),
        subject_id: v["subjectId"].as_str().unwrap(),
        ed25519_pub_hex: v["ed25519PubHex"].as_str().unwrap(),
        mldsa_pub_hex: v["mldsaPubHex"].as_str().unwrap(),
        issued_at: v["issuedAt"].as_u64().unwrap(),
        signature_hex: v["signature"].as_str().unwrap(),
    }
}

struct PinOwned {
    ids: Vec<String>,
    after: Option<(String, String)>,
}

impl PinOwned {
    fn new(v: &Value) -> Self {
        let ids = v["keyIds"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_str().unwrap().to_owned())
            .collect();
        let after = v["requirePqAfter"].as_object().map(|o| {
            (
                o["releaseId"].as_str().unwrap().to_owned(),
                o["commitHash"].as_str().unwrap().to_owned(),
            )
        });
        Self { ids, after }
    }
}

fn with_pin<R>(p: &PinOwned, f: impl FnOnce(&Pin<'_>) -> R) -> R {
    let ids: Vec<&str> = p.ids.iter().map(String::as_str).collect();
    let pin = Pin {
        key_ids: &ids,
        require_pq_after: p.after.as_ref().map(|(a, b)| (a.as_str(), b.as_str())),
    };
    f(&pin)
}

#[test]
fn statements_rebuild_byte_for_byte() {
    let v = vectors();
    let key_id = v["keys"]["release"]["keyId"].as_str().unwrap();
    for n in ["A", "B", "C", "D"] {
        let e = Owned::new(&v["endorsements"][n]);
        let st = &v["statements"][e.view().release_id];
        assert_eq!(
            hex(&v1_canonical(&e.view()).unwrap()),
            st["v1CanonicalHex"].as_str().unwrap()
        );
        assert_eq!(
            v1_digest(&e.view()).unwrap(),
            st["v1Digest"].as_str().unwrap()
        );
        assert_eq!(
            hex(&v2_statement(&e.view(), key_id).unwrap()),
            st["v2StatementHex"].as_str().unwrap()
        );
    }
}

#[test]
fn companion_cases() {
    let v = vectors();
    let now = v["now"].as_u64().unwrap();
    for c in v["companionCases"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let pin = PinOwned::new(&v["pins"][c["pin"].as_str().unwrap()]);
        let wires: Vec<BindingWire<'_>> = c["bindings"]
            .as_array()
            .unwrap()
            .iter()
            .map(|b| binding(&v["bindings"][b.as_str().unwrap()]))
            .collect();
        let e = Owned::new(&v["endorsements"][c["endorsement"].as_str().unwrap()]);
        let got = with_pin(&pin, |pin| {
            let (bindings, _) = verify_release_bindings(&wires, pin, now);
            if c["companion"].is_null() {
                verify_companion(&e.view(), None, pin, &bindings)
            } else {
                companion(&c["companion"])
                    .and_then(|w| verify_companion(&e.view(), Some(&w), pin, &bindings))
            }
        });
        let expect = &c["expect"];
        if expect["ok"].as_bool().unwrap() {
            assert_eq!(
                got.as_deref(),
                Ok(expect["keyId"].as_str().unwrap()),
                "{name}"
            );
        } else {
            assert_eq!(
                got.map_err(ReleaseError::code),
                Err(expect["code"].as_str().unwrap()),
                "{name}"
            );
        }
    }
}

#[test]
fn binding_cases() {
    let v = vectors();
    let now = v["now"].as_u64().unwrap();
    for c in v["bindingCases"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let pin = PinOwned::new(&v["pins"][c["pin"].as_str().unwrap()]);
        let w = binding(&v["bindings"][c["binding"].as_str().unwrap()]);
        let (ok, errors) = with_pin(&pin, |pin| verify_release_bindings(&[w], pin, now));
        let ids: Vec<String> = ok.iter().map(|b| hex(&b.hybrid_key().key_id())).collect();
        let want: Vec<&str> = c["expect"]["verified"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_str().unwrap())
            .collect();
        assert_eq!(ids, want, "{name}");
        let codes: Vec<&str> = errors.iter().map(|(_, c)| *c).collect();
        let want: Vec<&str> = c["expect"]["errors"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_str().unwrap())
            .collect();
        assert_eq!(codes, want, "{name}");
    }
}

#[test]
fn classify_cases() {
    let v = vectors();
    let now = v["now"].as_u64().unwrap();
    let names = ["A", "B", "C", "D"];
    let owned: Vec<Owned<'_>> = names
        .iter()
        .map(|n| Owned::new(&v["endorsements"][*n]))
        .collect();
    let es: Vec<ReleaseV1<'_>> = owned.iter().map(Owned::view).collect();
    for c in v["classifyCases"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let pin = PinOwned::new(&v["pins"][c["pin"].as_str().unwrap()]);
        let comps: Vec<CompanionWire<'_>> = c["companions"]
            .as_array()
            .unwrap()
            .iter()
            .map(|n| companion(&v["companions"][n.as_str().unwrap()]).unwrap())
            .collect();
        let wires: Vec<BindingWire<'_>> = c["bindings"]
            .as_array()
            .unwrap()
            .iter()
            .map(|b| binding(&v["bindings"][b.as_str().unwrap()]))
            .collect();
        let got = with_pin(&pin, |pin| {
            let (bindings, _) = verify_release_bindings(&wires, pin, now);
            classify(&es, &comps, &bindings, pin)
        });
        let pick = |k: &str| -> Vec<&str> {
            c["expect"][k]
                .as_array()
                .unwrap()
                .iter()
                .map(|x| x.as_str().unwrap())
                .collect()
        };
        assert_eq!(
            got.eligible.iter().map(|&i| names[i]).collect::<Vec<_>>(),
            pick("eligible"),
            "{name}"
        );
        assert_eq!(
            got.lineage_only
                .iter()
                .map(|&i| names[i])
                .collect::<Vec<_>>(),
            pick("lineageOnly"),
            "{name}"
        );
        let refused: Vec<(&str, &str)> = got
            .refused
            .iter()
            .map(|&(i, code)| (names[i], code))
            .collect();
        let want: Vec<(&str, &str)> = c["expect"]["refused"]
            .as_array()
            .unwrap()
            .iter()
            .map(|r| {
                (
                    r["endorsement"].as_str().unwrap(),
                    r["code"].as_str().unwrap(),
                )
            })
            .collect();
        assert_eq!(refused, want, "{name}");
    }
}
